          tuiWarning(
            'note: Context window exhausted — the request was not sent; '
            'auto-compacting…',
          ),
        );
        return;
      }
      io.writeln(
        _keyStatusView.errorLine(
          message.errorMessage ?? 'unknown error',
          _agent.state.model.baseUrl,
