  );
  final hasToolCalls = message.content.any((c) => c is ToolCall);
  if (!hasText && !hasToolCalls) {
    io.writeln(
      _style.dim(
        '(empty response: the model returned no text — '
        'it may be rate-limited or reasoning-only)',
      ),
    );
  }
}

