// when the run ends (including the error/aborted early return —
// [_terminalRunMessages]). The gate key is read per even…

blocks.text:
  // stashes what it stripped; [_emitFinalizeGateFold] consumes the stash
  // when the run ends (including the error/aborted early return —
  // [_terminalRunMessages]). The gate key is read per event from the
  // loop's live config so the interceptor and the fold always agree on
  // the same value; within a run it is constant — nothing in the loop
  // mutates `finalizeGate` mid-run.
  final strippedLedgers = <_StrippedLedger>[];
  if (config.finalizeGate) {
    emit = _finalizeGateStrippingSink(
      emit,
      strippedLedgers,
      () => currentConfig.finalizeGate,
    );
  }
  // Issue #862: breaker counters are per run (per user turn) — a fresh
  // prompt starts from zero consecutive failures.
  config.toolMisuseBreaker?.beginRun();

  await _emitRunStart(prompts, emit);

  var firstTurn = true;
  // Steering-extension cap: a self-sustaining chatter loop (every inbound
  // message steers a reply that triggers the next inbound) must not keep
  // the run alive forever. Undelivered steering stays queued; the next
  // run picks it up under its own wake caps.
  var steeringExtensions = 0;
  Future<List<Message>> pollSteering(AgentLoopConfig config) async {
    if (steeringExtensions >= config.maxSteeringTurns) {
      return const <Message>[];
    }
    final messages = await _steeringMessages(config);
    if (messages.isNotEmpty) steeringExtensions++;
    return messages;
  }

  // Check for steering messages at start (user may have typed while waiting).
  var pendingMessages = await pollSteering(currentConfig);

  // Outer loop: continues when queued follow-up messages arrive after the
  // agent would stop. Inner loop: tool calls and steering messages.
  while (true) {
    var hasMoreToolCalls = true;
    while (hasMoreToolCalls || pendingMessages.isNotEmpty) {
      await _emitTurnStart(firstTurn, emit);
      firstTurn = false;

      // Inject queued messages before the next assistant response.
      await _injectPendingMessages(
        pendingMessages,
        emit,
        currentContext,
        newMessages,
      );
      pendingMessages = const [];
      AssistantMessage message;
      (message, currentContext) = await _streamAssistantResponse(
        currentContext,
        currentConfig,
        emit,
        streamFunction,
        cancelToken,
      );
      (message, currentContext) = await _retryDegenerateEmpty(
        message,
        currentContext,
        currentConfig,
        emit,
        streamFunction,
        cancelToken,
      );
      newMessages.add(message);

      final terminal = await _terminalRunMessages(
        message,
        newMessages,
        currentContext.messages,
        strippedLedgers,
        currentConfig.finalizeGate,
        emit,
      );
      if (terminal != null) return terminal;

      final toolPhase = await _runToolCallPhase(
        currentContext,
        message,
        currentConfig,
        toolExecutor,
        cancelToken,
        emit,
        newMessages,
      );
      final toolResults = toolPhase.results;
      hasMoreToolCalls = toolPhase.hasMore;

      final turnResults = List<ToolResultMessage>.unmodifiable(toolResults);
      await emit(TurnEndEvent(message: message, toolResults: turnResults));
      final turnUpdate = await currentConfig.prepareNextTurn?.call(
        NextTurnContext(
          message: message,
          toolResults: turnResults,
          context: currentContext,
          newMessages: List.unmodifiable(newMessages),
        ),
      );
      (currentContext, currentConfig) = _applyTurnUpdate(
        currentContext,
        currentConfig,
        turnUpdate,
      );

      pendingMessages = await pollSteering(currentConfig);
    }

    // Agent would stop here. Check for follow-up messages.
    final followUpMessages =
        await currentConfig.getFollowUpMessages?.call() ?? const <Message>[];
    if (followUpMessages.isNotEmpty) {
      // Set as pending so the inner loop processes them.
      pendingMessages = followUpMessages;
      continue;
    }
    // Final steering drain (issue #314): a steer landing between the last
    // boundary poll and this stop-check would otherwise sit queued with no
    // run left to deliver it - the loop is still alive here, so open the
    // turn now. Cap-exhausted steering stays queued for the next run.
    pendingMessages = await pollSteering(currentConfig);
    if (pendingMessages.isNotEmpty) continue;

    break;
  }

  // The FinalizeGate (gh-1412, gh-1516): unattended runs fold the task
  // ledger out of the FINAL assistant message — see [_emitFinalizeGateFold].
  if (currentConfig.finalizeGate) {
    await _emitFinalizeGateFold(
      newMessages,
      currentContext.messages,
      strippedLedgers,
      emit,
    );
  }

  await emit(AgentEndEvent(List.unmodifiable(newMessages)));
  return newMessages;
}

/// Emits the run-start sequence: `agent_start`, the first `turn_start`, and
/// the lifecycle events of every prompt message.
Future<void> _emitRunStart(List<Message> prompts, AgentEventSink emit) async {
  await emit(const AgentStartEvent());
  await emit(const TurnStartEvent());
  for (final prompt in prompts) {
    await emit(MessageStartEvent(prompt));
    await emit(MessageEndEvent(prompt));
  }
}

/// Emits `turn_start` for every turn after the first (the first turn's start
/// was already emitted by [_emitRunStart]).
Future<void> _emitTurnStart(bool firstTurn, AgentEventSink emit) async {
  if (!firstTurn) await emit(const TurnStartEvent());
}

/// Ends the run when the assistant [message] failed or was aborted, emitting
/// the closing `turn_end`/`agent_end` and returning the run's messages.
/// Returns `null` for a healthy message so the turn continues.
///
/// The FinalizeGate fold runs on this path too (gh-1516 review): the
/// `MessageEndEvent` interceptor already stripped the ledger out of the
/// PERSISTED answer during the run, so without the fold an error/aborted
/// run would discard the hidden `task_ledger` record — the self-check of
/// precisely the near-miss case the gate exists to capture — and ship the
/// unstripped original in `AgentEndEvent`, disagreeing with the session
/// JSONL. An aborted run still ends on an assistant answer, so gh-1412's
/// "run must end on the answer" rule is satisfied.
Future<List<Message>?> _terminalRunMessages(
  AssistantMessage message,
  List<Message> newMessages,
  List<Message> contextMessages,
  List<_StrippedLedger> stash,
  bool finalizeGate,
  AgentEventSink emit,
) async {
  if (message.stopReason != StopReason.error &&
      message.stopReason != StopReason.aborted) {
    return null;
  }
  if (finalizeGate) {
    await _emitFinalizeGateFold(newMessages, contextMessages, stash, emit);
  }
  await emit(TurnEndEvent(message: message, toolResults: const []));
  await emit(AgentEndEvent(List.unmodifiable(newMessages)));
  return newMessages;
}

