    );
    final stream = AssistantMessageEventStream();
    final events = turns.removeAt(0);
    if (isFinal && cancelToken != null) {
      stream.push(StartEvent(partial: testAssistant()));
      cancelToken.onCancel.then((_) {
        for (final event in events) {
          stream.push(event);
        }
        stream.end();
      });
    } else {
      for (final event in events) {
        stream.push(event);
      }
      stream.end();
    }
    return stream;
