    // tests can tune N and pin the backoff.
    emptyHiccupRetries: config.emptyHiccupRetries,
    emptyHiccupBaseDelay: config.emptyHiccupBaseDelay,
    emptyHiccupMaxBackoff: config.emptyHiccupMaxBackoff,
