    final queuedFollowUps = _followUpQueue.drain();
    if (queuedFollowUps.isNotEmpty) {
      await _runPromptMessages(queuedFollowUps);
      return;
    }

    throw StateError('Cannot continue from message role: assistant');
  }

  await _runContinuation();
}

