String _brief(Message m) {
  if (m is AssistantMessage) return 'stop=${m.stopReason.name}';
  if (m is ToolResultMessage) return 'tool=${m.toolName}';
  if (m is UserMessage) {
    final c = m.content;
    return 'text=${c is String ? c.substring(0, c.length.clamp(0, 20)) : "blocks"}';
  }
  return '';
}
