    ];
    final truncatedToolCallTurn = toolTurn([
      const ToolCall(
        id: 'c1',
        name: 'bash',
        arguments: {'command': 'python3 - <<"unsigned long N = strtoull'},
      ),
    ]);
    final stream = FakeStreamFunction([
