      ),
      io: io,
      streamFunction: stream.call,
    );
    final run = cli.run();
    io.sendLine('do the task');
    for (var i = 0; i < 400; i++) {
      if (stream.calls >= 5 && !cli.isBusy) break;
      await Future<void>.delayed(const Duration(milliseconds: 25));
