  if (images.isEmpty) {
    await _agent.prompt(_redactUserText(prompt));
  } else {
    // --attach (issue #155): the files ride the first user message as
    // image content blocks next to the (redacted) prompt text.
    await _agent.promptMessage(
      UserMessage(
        content: [
          TextContent(text: _redactUserText(prompt)),
          ...images,
        ],
        timestamp: DateTime.now(),
      ),
    );
  }
  // Settle the finished turn exactly like the REPL's [_runPrompt]
  // (issue #413): the over-window guard's one-shot compaction +
  // continuation used to be REPL-only, so a headless run that
  // exhausted the window mid-task abandoned it and exited — the
  // freed window was never used.
  final lastMessage = _agent.state.messages.lastOrNull;
  final finished = await _settleAfterPrompt(
    lastMessage,
    isAutoContinue: false,
  );
  // gh-1603: captured BEFORE [_afterRun] — post-run compaction folds
  // assistant turns out of the visible transcript (issue #413), so the
  // last-message probe is only valid here. A run that still settles on
  // an empty completion after the nudge budget is an UNFINISHED session
  // (no final answer was produced); error/aborted terminals keep their
  // own exit codes below.
  final settledMessage = _agent.state.messages.lastOrNull;
  endedOnEmptyCompletion = settledMessage is AssistantMessage &&
      settledMessage.stopReason != StopReason.error &&
      settledMessage.stopReason != StopReason.aborted &&
      isEmptyAssistantCompletion(settledMessage);
